SELECT id AS memberId, name, email, phone, birth_date AS birthDate FROM members WHERE role = 'USER' AND status = 'ACTIVE' AND
id = #{keyword} name LIKE CONCAT('%', #{keyword}, '%') email LIKE CONCAT('%', #{keyword}, '%') phone LIKE CONCAT('%', #{keyword}, '%')
ORDER BY name, id LIMIT #{size} OFFSET #{offset}
